(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+y)*0.012-t*0.5)*8 + Math.cos((x-y)*0.01+t*0.4)*6;
  const w2y = Math.cos((x-y)*0.013+t*0.45)*8 + Math.sin((x+y)*0.009-t*0.35)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [80+Math.sin(t*0.65+3)*110, 40+Math.cos(t*0.45+2)*70, 0.11, 2.1, 1.3],
    [400+Math.cos(t*0.55+1)*95, 200+Math.sin(t*0.75+4)*65, 0.05, 1.8, 0.85]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp)*w;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    cS += Math.cos(d*f*1.3-t*sp*0.4+2.8)*w*0.5;
  }
  const wT = 8.75;
  const act=aS/wT, inh=iS/wT, cor=cS/wT;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.07-t*1.5)*Math.sin(sy*0.06+t*1.2)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2=Math.sin(dist*0.08+ang*2-t*2.2)*Math.cos(dist*0.03-ang*5+t*0.8)*0.25;
  const fine=(Math.sin(sx*0.25+t*1.8)*Math.sin(sy*0.22-t*1.4)
    +Math.sin((sx-sy)*0.18+t*2.5)*Math.cos((sx+sy)*0.15-t*1.9))*0.2;
  const cross=act*cor*0.3;
  const reaction=Math.tanh((act-inh*0.65+bg*0.25+sp1+sp2+fine+cross)*2.0);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.25;
  const vig=1-Math.pow(dist/320,2.5)*0.4;
  const blend=(reaction*0.65+cell*0.2+sp2*0.15)*vig;
  const v=blend*0.5+0.5;
  const pal=[
    [5,12,48],[10,42,82],[12,72,100],[18,110,115],
    [30,148,130],[80,170,110],[160,185,80],[210,175,60],
    [220,140,55],[210,95,65],[185,60,72],[140,35,68],
    [90,22,62],[45,15,55],[15,10,50],[5,12,48]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const pulse=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.65?1.12:Math.abs(reaction)>0.4?1.04:0.97;
  const spec=Math.pow(Math.max(0,reaction),4)*40;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*pulse*edge+spec*0.7)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*pulse*edge+spec*0.9)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*pulse*edge+spec*1.1)|0)
  ];
}
